--
-- Name: ash_trim_whitespace(text[]); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.ash_trim_whitespace(arr text[]) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    start_index INT = 1;
    end_index INT = array_length(arr, 1);
BEGIN
    WHILE start_index <= end_index AND arr[start_index] = '' LOOP
        start_index := start_index + 1;
    END LOOP;

    WHILE end_index >= start_index AND arr[end_index] = '' LOOP
        end_index := end_index - 1;
    END LOOP;

    IF start_index > end_index THEN
        RETURN ARRAY[]::text[];
    ELSE
        RETURN arr[start_index : end_index];
    END IF;
END; $$;


--
-- Name: build_timeseries_series_key(text, text, text, text, text, text, integer, jsonb); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.build_timeseries_series_key(p_metric_type text, p_metric_name text, p_partition text, p_agent_id text, p_device_id text, p_target_device_ip text, p_if_index integer, p_tags jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT md5(
    array_to_string(
      array_remove(
        ARRAY[
          platform.timeseries_series_component('metric_type', p_metric_type),
          platform.timeseries_series_component('metric_name', p_metric_name),
          platform.timeseries_series_component('partition', p_partition),
          platform.timeseries_series_component('agent_id', p_agent_id),
          platform.timeseries_series_component('device_id', p_device_id),
          platform.timeseries_series_component('target_device_ip', p_target_device_ip),
          platform.timeseries_series_component(
            'if_index',
            CASE WHEN p_if_index IS NULL THEN NULL ELSE p_if_index::text END
          ),
          platform.timeseries_series_stable_tags(p_tags)
        ],
        NULL
      ),
      '|'
    )
  )
$$;


--
-- Name: enforce_armis_northbound_ledger_immutability(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.enforce_armis_northbound_ledger_immutability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'integration_update_runs' THEN
    IF OLD.collection_id IS NOT NULL AND ROW(
      OLD.collection_id,
      OLD.collection_content_hash,
      OLD.collection_observed_at,
      OLD.raw_rows,
      OLD.excluded_rows,
      OLD.invalid_rows,
      OLD.valid_occurrences,
      OLD.distinct_source_ids,
      OLD.duplicate_occurrences,
      OLD.conflicting_duplicate_ids,
      OLD.eligible_count,
      OLD.withheld_count
    ) IS DISTINCT FROM ROW(
      NEW.collection_id,
      NEW.collection_content_hash,
      NEW.collection_observed_at,
      NEW.raw_rows,
      NEW.excluded_rows,
      NEW.invalid_rows,
      NEW.valid_occurrences,
      NEW.distinct_source_ids,
      NEW.duplicate_occurrences,
      NEW.conflicting_duplicate_ids,
      NEW.eligible_count,
      NEW.withheld_count
    ) THEN
      RAISE EXCEPTION 'northbound run collection binding is immutable'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    OLD.integration_update_run_id,
    OLD.collection_id,
    OLD.source_object_id,
    OLD.canonical_device_uid,
    OLD.eligibility,
    OLD.reason,
    OLD.is_available,
    OLD.metadata
  ) IS DISTINCT FROM ROW(
    NEW.integration_update_run_id,
    NEW.collection_id,
    NEW.source_object_id,
    NEW.canonical_device_uid,
    NEW.eligibility,
    NEW.reason,
    NEW.is_available,
    NEW.metadata
  ) THEN
    RAISE EXCEPTION 'northbound target disposition is immutable'
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.outcome <> 'pending' AND OLD.outcome IS DISTINCT FROM NEW.outcome THEN
    RAISE EXCEPTION 'northbound target terminal outcome is immutable'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


